/**
 * The whole CLI. Bare commands fan out across every platform; `handcart <platform> <cmd>` narrows to
 * one. The per-platform trees are generated by walking the registry, so adding a store is a descriptor
 * and no edit here.
 */
import { Command, InvalidArgumentError, Option } from "commander";
import { VERSION } from "../core/config.js";
import { HandcartError } from "../core/errors.js";
import type { Cart, Location, Order, Product, SearchOptions, Sort, Tagged } from "../core/types.js";
import { SORTS } from "../core/types.js";
import { HANDOFFS, type Handoff } from "../pay/index.js";
import {
  can,
  client,
  fanOut,
  type Platform,
  type PlatformDescriptor,
  platforms,
  reasonOf,
} from "../platforms/registry.js";
import { allOk, formatChecks, runDoctor } from "./doctor.js";
import * as fmt from "./format.js";
import { ask, closePrompts } from "./prompt.js";
import { registerSetup } from "./setup.js";

const int = (v: string) => {
  const n = Number.parseInt(v, 10);
  if (Number.isNaN(n)) throw new InvalidArgumentError("not a number");
  return n;
};
const num = (v: string) => {
  const n = Number(v);
  if (Number.isNaN(n)) throw new InvalidArgumentError("not a number");
  return n;
};

const withLocation = (c: Command) =>
  c
    .option("-p, --pincode <pincode>", "6-digit pincode (default: the platform's selected address/area)")
    .option("--lat <lat>", "latitude", num)
    .option("--lon <lon>", "longitude", num);

const withFilters = (c: Command) =>
  withLocation(c)
    .option("-n, --limit <n>", "number of results", int, 24)
    .addOption(new Option("-s, --sort <sort>", "sort order").choices(SORTS).default("relevance"))
    .option("--max-price <rupees>", "maximum price", num)
    .option("--min-price <rupees>", "minimum price", num)
    .option("--brand <brand>", "brand name contains")
    .option("--min-discount <pct>", "minimum discount %", int)
    .option("--in-stock", "only in-stock items")
    .option("-o, --out-of-stock", "also list sold-out items, after the in-stock ones (slower)")
    .option("--exact", "drop a store's 'related products' padding (shown by default)")
    .option("--json", "print JSON");

const searchOpts = (o: Record<string, unknown>): SearchOptions => ({
  pincode: o.pincode as string | undefined,
  lat: o.lat as number | undefined,
  lon: o.lon as number | undefined,
  limit: o.limit as number,
  sort: o.sort as Sort,
  maxPrice: o.maxPrice as number | undefined,
  minPrice: o.minPrice as number | undefined,
  brand: o.brand as string | undefined,
  minDiscount: o.minDiscount as number | undefined,
  inStock: !!o.inStock,
  includeOutOfStock: !!o.outOfStock,
  includeRelated: !o.exact,
});

const printCart = (o: { json?: boolean }) => (c: Cart) => (o.json ? fmt.json(c) : fmt.cart(c));

/** Sold-out items are hidden unless asked for, so an empty result should say how to see them. */
const soldOutHint = (o: Record<string, unknown>) => !o.outOfStock && !o.inStock;

const program = new Command("handcart")
  .description("Quick-commerce from the command line: search, compare, cart, checkout and UPI pay")
  .version(VERSION);

// ---------- fan-out: every platform at once ----------

withFilters(program.command("search <query>"))
  .description("search every platform and group the same product across them")
  .option("--by-platform", "plain per-platform lists instead of the merged comparison")
  .action(async (query, o) => {
    const opts = searchOpts(o);
    const { results, errors } = await fanOut("search", (p) => p.search(query, opts));
    const tagged: Tagged<Product>[] = results.flatMap(({ platform, value }) =>
      value.map((item) => ({ ...item, platform })),
    );
    if (o.json) {
      // The errors ride inside the JSON; printing them again would break the parse.
      fmt.json(fmt.taggedJson(query, tagged, errors));
      return;
    }
    if (o.byPlatform) fmt.byPlatform(results);
    else fmt.merged(query, tagged, o.pincode);
    fmt.failures(errors);
  });

program
  .command("cart")
  .description("every open cart, one block per platform")
  .option("--json", "print JSON")
  .action(async (o) => {
    const { results, errors } = await fanOut("cart", (p) => p.cart());
    if (o.json) fmt.json({ results, errors });
    else {
      for (const { platform, value } of results) {
        console.log(`\n${platform}`);
        fmt.cart(value);
      }
      fmt.failures(errors);
    }
  });

program
  .command("orders")
  .description("recent orders from every platform, newest first")
  .option("--json", "print JSON")
  .action(async (o) => {
    const { results, errors } = await fanOut("orders", async (p) => (await p.orders?.()) ?? []);
    const tagged: Tagged<Order>[] = results.flatMap(({ platform, value }) =>
      value.map((order) => ({ ...order, platform })),
    );
    if (o.json) fmt.json({ results: tagged, errors });
    else {
      fmt.mergedOrders(tagged);
      fmt.failures(errors);
    }
  });

program
  .command("whoami")
  .description("one line per platform: logged in, and where it delivers")
  .option("--json", "print JSON")
  .action(async (o) => {
    // Keyed on `login` because "is this platform usable" only means something where you log in.
    const { results, errors } = await fanOut("login", (p) => p.whoami());
    if (o.json) fmt.json({ results, errors });
    else {
      const width = Math.max(0, ...results.map((r) => r.platform.length));
      for (const { platform, value } of results) fmt.session(platform, value, width);
      fmt.failures(errors);
    }
  });

// ---------- handcart level ----------

program
  .command("location <pincode>")
  .description("set one delivery pincode on every platform that can shop without login")
  .option("--json", "print JSON")
  .action(async (pincode, o) => {
    const fn = async (p: Platform): Promise<Location | undefined> => p.setLocation?.({ pincode });
    const { results, errors } = await fanOut("locate", fn);
    if (o.json) fmt.json({ results, errors });
    else {
      for (const { platform, value } of results) console.log(`${platform}: ${value?.address ?? pincode}`);
      fmt.failures(errors);
    }
  });

program
  .command("platforms")
  .description("supported platforms, their state and what each can do")
  .option("--json", "print JSON")
  .action(async (o) => {
    const list = await Promise.all(platforms().map(async (d) => ({ descriptor: d, state: await state(d) })));
    if (o.json) fmt.json(list.map(({ descriptor: d, state }) => ({ ...d, create: undefined, state })));
    else fmt.platforms(list);
  });

program
  .command("mcp")
  .description("run as an MCP stdio server")
  .action(async () => {
    const { runMcp } = await import("../mcp/server.js");
    await runMcp();
  });

registerSetup(program);

/** One phrase for `handcart platforms`: usable, half-configured, or why not. */
async function state(d: PlatformDescriptor): Promise<string> {
  try {
    const who = await client(d.name).whoami();
    if (!who.loggedIn) return `not logged in — run \`handcart ${d.name} login <phone>\``;
    if (!who.deliverTo) return `logged in, no delivery address — run \`handcart ${d.name} address\``;
    return `ready · [${who.deliverTo.label ?? "—"}] ${who.deliverTo.text}`;
  } catch (e) {
    return reasonOf(e);
  }
}

// ---------- one platform ----------

function registerDoctor(c: Command, only?: PlatformDescriptor[]): void {
  c.command("doctor")
    .description("check everything needed to shop and pay, and say how to fix what's missing")
    .option("--json", "print JSON")
    .action(async (o) => {
      const checks = await runDoctor(only ? { only } : {});
      if (o.json) fmt.json(checks);
      else console.log(formatChecks(checks));
      if (!allOk(checks)) process.exitCode = 1;
    });
}

registerDoctor(program);

/** The whole subcommand tree for one platform, capability-gated. */
function registerPlatform(d: PlatformDescriptor): void {
  const p = (): Platform => client(d.name);
  const cmd = program.command(d.name).description(`${d.label} only`);

  if (can(d, "search")) {
    withFilters(cmd.command("search <query>"))
      .description(`search ${d.label}`)
      .action(async (query, o) => {
        const items = await p().search(query, searchOpts(o));
        o.json ? fmt.json(items) : fmt.products(items, soldOutHint(o));
      });
  }

  if (can(d, "product")) {
    cmd
      .command("product <id>")
      .description("product details: price, stock, attributes")
      .option("--json", "print JSON")
      .action(async (id, o) => {
        const item = await p().product(id);
        o.json ? fmt.json(item) : fmt.product(item);
      });
  }

  if (can(d, "categories")) {
    cmd
      .command("categories [name]")
      .description("category tree, or one group/category's contents")
      .option("--json", "print JSON")
      .action(async (name, o) => {
        if (name) {
          const found = await p().findCategory?.(name);
          o.json || !found ? fmt.json(found) : fmt.categoryMatch(found);
        } else {
          const tree = (await p().categories?.()) ?? [];
          o.json ? fmt.json(tree) : fmt.categoryTree(tree);
        }
      });
  }

  if (can(d, "browse")) {
    withFilters(cmd.command("browse <category>"))
      .description("list products in a category or subcategory, e.g. Milk or 'Dairy, Bread & Eggs'")
      .action(async (category, o) => {
        const r = await p().browse?.(category, searchOpts(o));
        o.json || !r ? fmt.json(r) : fmt.browse(r);
      });
  }

  if (can(d, "locate")) {
    cmd
      .command("locate <pincode>")
      .description(`resolve a pincode to ${d.label} coordinates (does not change the session)`)
      .action(async (pincode) => fmt.json(await p().locate?.(pincode)));
  }

  if (can(d, "login")) {
    cmd
      .command("login <phone>")
      .description("log in with an SMS OTP")
      .option("--otp <code>", "OTP (otherwise prompted)")
      .option("--send-only", `only send the OTP; finish with \`handcart ${d.name} verify <code>\``)
      .action(async (phone, o) => {
        const sent = await p().requestOtp(phone);
        console.log(`OTP sent to ${sent.to}.`);
        if (o.sendOnly) return;
        const code = (o.otp as string | undefined) ?? (await ask("Enter OTP: "));
        fmt.json(await p().verifyOtp(code));
      });
    cmd
      .command("verify <code>")
      .description("finish login with the OTP from SMS")
      .action(async (code) => fmt.json(await p().verifyOtp(code)));
    cmd
      .command("logout")
      .description("forget the saved session")
      .action(async () => fmt.json(await p().logout()));
  }

  cmd
    .command("whoami")
    .description("session: logged in, and where it delivers")
    .option("--json", "print JSON")
    .action(async (o) => {
      const who = await p().whoami();
      o.json ? fmt.json(who) : fmt.session(d.name, who);
    });

  if (can(d, "addresses")) {
    const address = cmd.command("address").description("saved delivery addresses");
    address
      .command("list", { isDefault: true })
      .option("--json", "print JSON")
      .action(async (o) => {
        const list = await p().addresses();
        o.json ? fmt.json(list) : fmt.addresses(list);
      });
    address
      .command("use <which>")
      .description("deliver to a saved address: label, id, or part of the text")
      .action(async (which) => {
        const a = await p().useAddress(which);
        console.log(`Delivering to [${a.label ?? "—"}] ${a.text}`);
      });
  }

  if (can(d, "cart")) {
    const cart = cmd.command("cart").description("server-priced cart");
    cart
      .command("show", { isDefault: true })
      .option("--json", "print JSON")
      .action(async (o) => printCart(o)(await p().cart()));
    cart
      .command("add <id> [qty]")
      .description("add quantity on top of what's in the cart")
      .option("--json", "print JSON")
      .action(async (id, qty, o) => printCart(o)(await p().add(id, qty ? int(qty) : 1)));
    cart
      .command("set <id> <qty>")
      .description("set an absolute quantity (0 removes)")
      .option("--json", "print JSON")
      .action(async (id, qty, o) => printCart(o)(await p().setQuantity(id, int(qty))));
    cart
      .command("remove <id>")
      .option("--json", "print JSON")
      .action(async (id, o) => printCart(o)(await p().setQuantity(id, 0)));
    cart
      .command("clear")
      .option("--json", "print JSON")
      .action(async (o) => printCart(o)(await p().clear()));
  }

  if (can(d, "checkout")) {
    cmd
      .command("checkout")
      .description("validate the cart for your address and show the payable bill")
      .option("--json", "print JSON")
      .action(async (o) => {
        const b = await p().checkout();
        o.json ? fmt.json(b) : fmt.bill(b);
      });
  }

  if (can(d, "orders")) {
    cmd
      .command("orders")
      .description("recent orders, newest first")
      .option("--json", "print JSON")
      .action(async (o) => {
        const list = (await p().orders?.()) ?? [];
        o.json ? fmt.json(list) : fmt.orders(list);
      });
  }

  if (can(d, "pay")) {
    cmd
      .command("pay")
      .description("pay by UPI: places the order and gives you a qrbaton pay link (or just the QR with --handoff qr)")
      .requiredOption("--confirm <rupees>", "the exact amount to pay, as shown by `checkout`", num)
      .addOption(
        new Option("--handoff <how>", "qrbaton: pay page link with the order summary; qr: just the UPI QR image")
          .choices(HANDOFFS)
          .default("qrbaton"),
      )
      .option("--agent <name>", "shown on the pay page as who prepared the order")
      .option("--timeout <sec>", "seconds to wait for payment", int, 600)
      .option("--dry-run", "prepare the payment but don't generate a QR")
      .option("--browser", "drive the store's site in Chromium instead of its HTTP API (where supported)")
      .option("--no-open", "don't open the link / QR locally; just print it (agent handoff)")
      .action(async (o) => {
        const r = await p().pay?.({
          confirmAmount: o.confirm,
          timeoutSec: o.timeout,
          dryRun: o.dryRun,
          browser: o.browser,
          handoff: o.handoff as Handoff,
          agent: o.agent,
          openPage: o.open,
        });
        if (!r) return;
        const msg: Record<string, string> = {
          paid: "Payment done, order placed.",
          failed: "Payment failed.",
          timeout: "Timed out waiting for payment.",
          browser_closed: "Browser closed before payment.",
          dry_run_ok: "Dry run OK.",
          qr_ready: "UPI QR ready.",
        };
        console.log(msg[r.stage] ?? r.stage);
        if (r.error) console.log("error:", r.error);
      });
  }

  registerDoctor(cmd, [d]);
}

for (const d of platforms()) registerPlatform(d);

export async function run(argv = process.argv): Promise<void> {
  try {
    await program.parseAsync(argv);
  } catch (e) {
    if (!(e instanceof HandcartError)) throw e;
    console.error(`error: ${e.message}`);
    process.exitCode = 1;
  } finally {
    closePrompts(); // a prompt holds stdin open, which would keep the process alive after the command
  }
}
